#!/bin/sh
# Commit-msg hook: reject commit messages that attribute the commit to an AI
# assistant.
#
# Usage: block-claude-authorship.sh <commit-message-file>
#
# Fails, matching case-insensitively, on:
#   - a "generated with" or "generated by" notice naming Claude, Anthropic or
#     another AI tool, with or without an emoji or a link;
#   - a robot-emoji "generated" notice;
#   - an attribution trailer (Co-authored-by:, Assisted-by:, ...) naming
#     Claude, Anthropic or an AI assistant;
#   - an Anthropic noreply e-mail address.
# Lines starting with '#', and everything below git's scissors line, are
# ignored. Ordinary mentions, such as "docs: Update CLAUDE.md", pass.

if [ "$#" -ne 1 ] || [ ! -r "$1" ]; then
    echo "usage: $0 <commit-message-file>" >&2
    exit 2
fi

# Compare bytes, whatever the user's locale.
LC_ALL=C
export LC_ALL

# AI assistants and their vendors.
ai_names='claude|anthropic|openai|chatgpt|gpt-?[0-9]|codex|copilot|gemini|cursor[ -]?agent|devin[ -]ai|aider|codeium|windsurf|tabnine|codewhisperer'
# Generic descriptions of an AI author, checked in trailers only.
ai_words='[^[:alnum:]]ai[[:space:]-]*(agent|bot|model)|[^[:alnum:]]ai[[:space:]]*(<|$)|[^[:alnum:]]llm([^[:alnum:]]|$)|assistant|language model'
robot=$(printf '\360\237\244\226') # U+1F916 ROBOT FACE in UTF-8

generated="generated[[:space:]]+(with|by|using)[^[:alnum:]]*(https?://(www\\.)?)?($ai_names)"
robot_generated="${robot}[^[:alnum:]]*generated"
trailer='^[[:space:]]*[[:alnum:]-]+-by[[:space:]]*:'
noreply='noreply@anthropic\.com'

matches() {
    printf '%s\n' "$1" | grep -Eiq -e "$2"
}

status=0
lineno=0
while IFS= read -r line || [ -n "$line" ]; do
    lineno=$((lineno + 1))
    case $line in
        '# ------------------------ >8 ------------------------'*) break ;;
        '#'*) continue ;;
    esac

    reason=
    if matches "$line" "$generated" || matches "$line" "$robot_generated"; then
        reason='generated-with notice'
    elif matches "$line" "$trailer" &&
        { matches "$line" "$ai_names" || matches "$line" "$ai_words"; }; then
        reason='AI attribution trailer'
    elif matches "$line" "$noreply"; then
        reason='Anthropic noreply address'
    fi

    if [ -n "$reason" ]; then
        if [ "$status" -eq 0 ]; then
            echo 'Commit message contains AI attribution:' >&2
        fi
        printf '  line %d (%s): %s\n' "$lineno" "$reason" "$line" >&2
        status=1
    fi
done <"$1"

if [ "$status" -ne 0 ]; then
    echo 'Remove these lines from the commit message and commit again.' >&2
fi
exit "$status"
